  // ------------------------------------------------------------------ РОЗДІЛ 3
  r.h1("РОЗДІЛ 3. МЕТОДИ ПІДБОРУ АВТО, ЗАПОВНЕННЯ ПАРАМЕТРІВ І ПОШУКУ В БАЗІ ЗНАНЬ", { chapter: 3 });
  r.h2("3.1. Заповнення параметрів (slot filling)");
  r.p(`Між моделлю та інструментами розташовано шар заповнення параметрів. У класичних діалогових системах слоти заповнює окремий модуль розуміння мови [9]; в LLM-агенті їх «заповнює» сама модель, передаючи аргументи інструменту. Проблема в тому, що модель робить це без гарантій: може пропустити параметр, названий кілька реплік тому, або вигадати відсутній. Запропонований механізм не замінює модель, а контролює її: кожен виклик інструмента перед виконанням проходить через SlotFillingEngine (рис. {fig:sf}).`);
  r.fig("dg_slot_filling.png", "Алгоритм заповнення параметрів перед викликом інструмента", { key: "sf", w: 520 });
